/* Блок: Шапка сайта + бургер-меню — САМОДОСТАТОЧНЫЙ скрипт блока.
   Всё поведение шапки: контраст логотипа/текста под текущей секцией, языковой
   переключатель, подсветка активного пункта (в строке и в drawer), нормализация
   ссылок и открытие/закрытие полноэкранного бургер-меню.
   Аналитика (trackEvent) — опциональна: вызывается через window.trackEvent?.(),
   поэтому блок работает и без common.js. syncLogoContrast экспортируется в window
   (его дёргает слайдер героя в bloks/hero-stage при смене слайда).

   Контраст (syncLogoContrast) — УНИВЕРСАЛЬНЫЙ, без whitelist классов:
     1) открытый бургер-drawer → всегда светлый UI (тёмный оверлей);
     2) явная метка секции data-header-theme="dark|light" (фото/видео — авто их
        не видит) имеет приоритет;
     3) иначе — авто по фону под шапкой: сплошной background-color или стопы
        градиента (см. contrastCore, YIQ-яркость, порог BRIGHT_THRESHOLD);
     4) ничего не определилось (сплошь медиа без меток) → дефолт тёмный
        (светлый текст) — правило «над фото текст не чернить». */
(() => {
  // Все пункты меню: и в строке (.gmenu), и в полноэкранном drawer.
  const menuLinks = () => document.querySelectorAll(".gmenu a, .gnav-drawer-menu a");

  // --- contrastCore (инлайн из contrastCore.js; правь ТАМ, не здесь) ---
/* Contrast core — ЧИСТАЯ логика определения «тёмный/светлый фон».
 *
 * Один источник правды:
 *   - тестируется напрямую в contrastCore.test.ts (require этого файла);
 *   - инлайнится в браузерный globalJs шапки: сборщик вырезает node-хвост
 *     (экспорт ниже) и вставляет тело в IIFE на месте маркера ядра.
 * Поэтому: НЕ импортируй сюда ничего, не используй DOM — только строки и числа.
 */

// YIQ-яркость 0..255. Порог BRIGHT_THRESHOLD делит на тёмный/светлый.
var BRIGHT_THRESHOLD = 140

function relBrightness(r, g, b) {
  return (r * 299 + g * 587 + b * 114) / 1000
}

// Разбирает первый rgb()/rgba() из строки в [r,g,b,a] или null.
function parseRgb(str) {
  var m = /rgba?\(([^)]+)\)/.exec(str || '')
  if (!m) return null
  var p = m[1].split(',').map(function (s) { return parseFloat(s) })
  if (p.length < 3) return null
  if (isNaN(p[0]) || isNaN(p[1]) || isNaN(p[2])) return null
  return [p[0], p[1], p[2], p.length >= 4 && !isNaN(p[3]) ? p[3] : 1]
}

// Сплошной background-color → яркость 0..255, или null если прозрачнее .5
// (полупрозрачный фон не определяет цвет — решает слой под ним).
function colorBrightness(str) {
  var c = parseRgb(str)
  if (!c || c[3] < 0.5) return null
  return relBrightness(c[0], c[1], c[2])
}

// background-image со стопами градиента → средняя яркость стопов с alpha>=.3,
// или null (url()-картинка/видео/нет градиента — цвет неопределим).
function gradientBrightness(str) {
  if (!str || str.indexOf('gradient') === -1) return null
  var re = /rgba?\(([^)]+)\)/g
  var m, sum = 0, n = 0
  while ((m = re.exec(str))) {
    var p = m[1].split(',').map(function (s) { return parseFloat(s) })
    if (p.length < 3 || isNaN(p[0]) || isNaN(p[1]) || isNaN(p[2])) continue
    var a = p.length >= 4 && !isNaN(p[3]) ? p[3] : 1
    if (a < 0.3) continue
    sum += relBrightness(p[0], p[1], p[2])
    n++
  }
  return n ? sum / n : null
}

// backgroundColor + backgroundImage (getComputedStyle) → 'dark' | 'light' | null.
// Цвет приоритетнее градиента. null = фон неопределим (медиа/прозрачно).
function themeFromStyle(backgroundColor, backgroundImage) {
  var b = colorBrightness(backgroundColor)
  if (b === null) b = gradientBrightness(backgroundImage)
  if (b === null) return null
  return b < BRIGHT_THRESHOLD ? 'dark' : 'light'
}
  // --- /contrastCore ---

  const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

  // Тема под точкой (x,y): идём по всему стеку элементов сверху вниз (elementsFromPoint
  // включает и предков-секции, и слайды под негативным z-index). Первый определившийся
  // слой побеждает: сам хедер пропускаем; затем метка data-header-theme; затем фон.
  function themeUnderPoint(x, y) {
    const stack = document.elementsFromPoint(x, y);
    for (const el of stack) {
      if (el.closest(".gnav")) continue;
      const attr = el.getAttribute("data-header-theme");
      if (attr === "dark" || attr === "light") return attr;
      const cs = getComputedStyle(el);
      const theme = themeFromStyle(cs.backgroundColor, cs.backgroundImage);
      if (theme) return theme;
    }
    return null;
  }

  function syncLogoContrast() {
    const nav = document.querySelector(".gnav");
    if (!nav) return;

    // Открытый бургер-drawer = тёмный полноэкранный оверлей → всегда светлый UI.
    if (document.querySelector(".gnav-drawer.is-open")) {
      nav.classList.add("logo-light");
      nav.classList.remove("logo-dark");
      return;
    }

    const box = nav.getBoundingClientRect();
    const y = clamp(box.bottom + 12, 1, window.innerHeight - 1);
    // Три пробы по нижней кромке (лево/центр/право) — устойчивее к колонкам и краям.
    const xs = [0.15, 0.5, 0.85].map((f) => clamp(box.left + box.width * f, 1, window.innerWidth - 1));

    let dark = 0, light = 0;
    for (const x of xs) {
      const t = themeUnderPoint(x, y);
      if (t === "dark") dark++;
      else if (t === "light") light++;
    }
    // Ничего не определилось (сплошь медиа без меток) → дефолт тёмный (светлый текст).
    const isDark = dark + light === 0 ? true : dark >= light;

    nav.classList.toggle("logo-light", isDark);
    nav.classList.toggle("logo-dark", !isDark);
  }

  function ensureLanguageOptions() {
    document.querySelectorAll(".language-switch").forEach((switcher) => {

      switcher.querySelectorAll("button").forEach((button) => {
        if (!button.dataset.lang) {
          button.dataset.lang = button.textContent.trim().toLowerCase();
        }

        button.addEventListener("click", () => {
          switcher.querySelectorAll("button").forEach((item) => {
            item.classList.toggle("active", item === button);
            item.setAttribute("aria-pressed", item === button ? "true" : "false");
          });
          document.documentElement.lang = button.dataset.lang === "uz" ? "uz" : button.dataset.lang;
          window.trackEvent?.("language_change", { language: button.dataset.lang });
        });
      });
    });
  }

  function normalizeNavigation() {
    menuLinks().forEach((link) => {
      const href = link.getAttribute("href") || "";
      if (href.includes("offers.html")) {
        link.remove();
      }
    });

    document.querySelectorAll(".nav-actions > .gbook").forEach((control) => {
      const phoneHref = "tel:+998781501111";
      const phoneLabel = "+998 78 150-11-11";

      if (control.tagName.toLowerCase() === "a") {
        control.href = phoneHref;
        control.setAttribute("aria-label", "Позвонить в Golden House");
        const label = control.querySelector(".label") || control;
        label.textContent = phoneLabel;
        return;
      }

      const phoneLink = document.createElement("a");
      phoneLink.className = control.className;
      phoneLink.href = phoneHref;
      phoneLink.setAttribute("aria-label", "Позвонить в Golden House");
      phoneLink.innerHTML = `<span class="label">${phoneLabel}</span><span class="arw" aria-hidden="true">&#8599;</span>`;
      control.replaceWith(phoneLink);
    });
  }

  function setupActiveNavigation() {
    const links = Array.from(menuLinks());
    if (!links.length) return;

    const getFile = (url) => (url.pathname.split("/").pop() || "index.html").toLowerCase();
    const getCurrentFile = () => (location.pathname.split("/").pop() || "index.html").toLowerCase();

    const setActive = (activeLink) => {
      const activeHref = activeLink.getAttribute("href");
      // Подсвечиваем совпадающие ссылки и в строке, и в drawer.
      links.forEach((link) => link.classList.toggle("active", link.getAttribute("href") === activeHref));
    };

    const findByHash = (hash) => links.find((link) => {
      const url = new URL(link.getAttribute("href"), location.href);
      return url.hash === hash;
    });

    const applyActiveFromLocation = () => {
      const file = getCurrentFile();
      const hash = location.hash || "#top";
      let activeLink = null;

      if (file === "complex-detail.html") {
        activeLink = findByHash("#complexes");
      } else if (file === "offers.html") {
        activeLink = links.find((link) => getFile(new URL(link.getAttribute("href"), location.href)) === "news.html");
      } else if (file === "index.html") {
        activeLink = findByHash(hash) || findByHash("#top");
      } else {
        activeLink = links.find((link) => {
          const url = new URL(link.getAttribute("href"), location.href);
          return getFile(url) === file && !url.hash;
        });
      }

      if (activeLink) setActive(activeLink);
    };

    links.forEach((link) => {
      link.addEventListener("click", () => setActive(link));
    });

    window.addEventListener("hashchange", applyActiveFromLocation);
    applyActiveFromLocation();
  }

  function setupBurgerMenu() {
    const burger = document.querySelector(".gburger");
    const drawer = document.querySelector(".gnav-drawer");
    if (!burger || !drawer) return;

    const isOpen = () => drawer.classList.contains("is-open");

    function openMenu() {
      drawer.classList.add("is-open");
      burger.classList.add("is-active");
      burger.setAttribute("aria-expanded", "true");
      burger.setAttribute("aria-label", "Закрыть меню");
      document.body.classList.add("gnav-menu-open");
      syncLogoContrast();
      window.trackEvent?.("burger_menu_open");
    }

    function closeMenu() {
      drawer.classList.remove("is-open");
      burger.classList.remove("is-active");
      burger.setAttribute("aria-expanded", "false");
      burger.setAttribute("aria-label", "Открыть меню");
      document.body.classList.remove("gnav-menu-open");
      syncLogoContrast();
    }

    burger.addEventListener("click", () => {
      isOpen() ? closeMenu() : openMenu();
    });

    drawer.querySelector(".gnav-drawer-close")?.addEventListener("click", closeMenu);
    drawer.addEventListener("click", (event) => {
      if (event.target === drawer) closeMenu();
    });
    drawer.querySelectorAll(".gnav-drawer-menu a").forEach((link) => {
      link.addEventListener("click", closeMenu);
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && isOpen()) closeMenu();
    });

    // На десктопе меню видно в строке — drawer закрываем.
    window.addEventListener("resize", () => {
      if (window.innerWidth > 1180 && isOpen()) closeMenu();
    });
  }

  function boot() {
    normalizeNavigation();
    ensureLanguageOptions();
    setupActiveNavigation();
    setupBurgerMenu();
    syncLogoContrast();
  }

  // Экспорт для слайдера героя (bloks/hero-stage дёргает при смене слайда).
  window.syncLogoContrast = syncLogoContrast;

  // rAF-троттлинг: syncLogoContrast теперь дороже (elementsFromPoint + getComputedStyle
  // по стеку × 3 пробы), поэтому не зовём его на каждый scroll-тик напрямую.
  let ticking = false;
  const requestSync = () => {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(() => {
      ticking = false;
      syncLogoContrast();
    });
  };

  window.addEventListener("scroll", requestSync, { passive: true });
  window.addEventListener("resize", requestSync);
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();

metadata.globalCss:
/* Блок: Шапка сайта (.gnav) — block-уровень globalCss.
   Зависит от токенов common.css (--gold/--white/--ink). Кнопка .gbook —
   общий компонент (стили в common.css), здесь только nav-специфика. */

.gnav {
  position: fixed;
  top: clamp(10px, 1.45vw, 18px);
  left: 50%;
  z-index: 9999;
  width: min(calc(100% - clamp(20px, 2.9vw, 36px)), 1432px);
  padding: clamp(12px, 1.3vw, 18px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  overflow: hidden;
  border: 1px solid rgba(253, 184, 42, .82);
  border-radius: clamp(18px, 2.2vw, 28px);
  background: rgba(255, 255, 255, .08);
  box-shadow: 0 18px 44px rgba(0, 0, 0, .18), 0 0 28px rgba(253, 184, 42, .18), inset 0 0 0 1px rgba(255, 255, 255, .08);
  transform: translateX(-50%);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.gnav::before,
.gnav::after {
  content: "";
  position: absolute;
  pointer-events: none;
}

.gnav::before {
  inset: 0;
  padding: 1px;
  border-radius: inherit;
  background: linear-gradient(115deg, #fdb82a, #fff1b6, #c98715, #fdb82a, #fff6cf);
  background-size: 260% 260%;
  opacity: .9;
  animation: navGoldFlow 4.6s ease-in-out infinite;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}

.gnav::after {
  top: -70%;
  bottom: -70%;
  left: -40%;
  width: 32%;
  background: linear-gradient(110deg, transparent, rgba(255, 255, 255, .34), transparent);
  transform: rotate(12deg);
  animation: navGoldShine 5.4s ease-in-out infinite;
}

.gnav > * {
  position: relative;
  z-index: 1;
}

@keyframes navGoldFlow {
  0%,
  100% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 50%;
  }
}

@keyframes navGoldShine {
  0% {
    left: -44%;
    opacity: 0;
  }

  24% {
    opacity: .8;
  }

  52%,
  100% {
    left: 112%;
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gnav::before,
  .gnav::after {
    animation: none;
  }
}

.glogo {
  display: inline-flex;
  align-items: center;
  min-width: 134px;
}

.glogo img {
  width: clamp(118px, 10vw, 154px);
  height: 42px;
  object-fit: contain;
  object-position: left center;
  transform: translateX(5px);
  filter: drop-shadow(0 2px 16px rgba(0, 0, 0, .2));
  transition: filter .25s ease, opacity .25s ease, transform .25s ease;
}

.gnav.logo-light .glogo img {
  filter: brightness(0) invert(1) drop-shadow(0 2px 16px rgba(0, 0, 0, .28));
}

.gnav.logo-dark .glogo img {
  filter: drop-shadow(0 2px 16px rgba(0, 0, 0, .2));
}

.gnav.logo-dark .gmenu,
.gnav.logo-dark .gbook,
.gnav.logo-dark .language-switch,
.gnav.logo-dark .gburger {
  border-color: rgba(21, 24, 29, .08);
  background: rgba(255, 255, 255, .58);
}

.gnav.logo-dark .gmenu a:not(.active),
.gnav.logo-dark .gbook,
.gnav.logo-dark .language-switch button:not(.active),
.gnav.logo-dark .gburger {
  color: rgba(21, 24, 29, .72);
}

.gmenu {
  display: flex;
  align-items: center;
  gap: 2px;
  max-width: min(860px, 58vw);
  padding: 5px;
  overflow-x: auto;
  border: 1px solid rgba(255, 255, 255, .28);
  border-radius: 999px;
  background: rgba(255, 255, 255, .14);
  scrollbar-width: none;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.gmenu::-webkit-scrollbar {
  display: none;
}

.gmenu a {
  padding: 9px 13px;
  border-radius: 999px;
  color: rgba(255, 255, 255, .9);
  font-size: 13px;
  transition: background .25s ease, color .25s ease;
  white-space: nowrap;
}

.gmenu a.active {
  background: var(--white);
  color: var(--ink);
  font-weight: 700;
}

.gmenu a:not(.active):hover {
  background: rgba(255, 255, 255, .16);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* Кнопка-телефон .gbook. Дублируется из common.css, чтобы шапка была
   самодостаточна (в редакторе блока / без site-CSS common.css не подгружен). */
.nav-actions .gbook {
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 11px 13px 11px 20px;
  border: 1px solid rgba(255, 255, 255, .3);
  border-radius: 999px;
  background: rgba(255, 255, 255, .16);
  color: var(--white, #fff);
  cursor: pointer;
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  transition: transform .25s ease, background .25s ease;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.nav-actions .gbook:hover {
  background: rgba(255, 255, 255, .26);
  transform: translateY(-1px);
}

.nav-actions .gbook .arw {
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--white, #fff);
  color: var(--ink, #15181d);
  font-size: 15px;
  font-weight: 900;
}

.language-switch {
  min-width: 86px;
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 6px;
  border: 1px solid rgba(255, 255, 255, .3);
  border-radius: 999px;
  background: rgba(255, 255, 255, .16);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.language-switch button {
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: rgba(255, 255, 255, .82);
  cursor: pointer;
  font-size: 12px;
  font-weight: 800;
}

.language-switch button.active {
  background: var(--white);
  color: var(--ink);
}

/* --- Кнопка-бургер (видна ≤1180px; drawer и его стили — в common.css) --- */
.gburger {
  display: none;
  width: 48px;
  height: 48px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, .3);
  border-radius: 50%;
  background: rgba(255, 255, 255, .16);
  color: rgba(255, 255, 255, .92);
  cursor: pointer;
  transition: background .25s ease;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.gburger:hover {
  background: rgba(255, 255, 255, .26);
}

.gburger-lines {
  position: relative;
  display: block;
  width: 22px;
  height: 14px;
}

.gburger-lines span {
  position: absolute;
  left: 0;
  width: 100%;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
  transition: top .3s ease, bottom .3s ease, transform .3s ease, opacity .2s ease;
}

.gburger-lines span:nth-child(1) {
  top: 0;
}

.gburger-lines span:nth-child(2) {
  top: 50%;
  transform: translateY(-50%);
}

.gburger-lines span:nth-child(3) {
  bottom: 0;
}

/* Открыто → бургер превращается в крестик */
.gburger.is-active .gburger-lines span:nth-child(1) {
  top: 50%;
  transform: translateY(-50%) rotate(45deg);
}

.gburger.is-active .gburger-lines span:nth-child(2) {
  opacity: 0;
}

.gburger.is-active .gburger-lines span:nth-child(3) {
  top: 50%;
  bottom: auto;
  transform: translateY(-50%) rotate(-45deg);
}

@media (prefers-reduced-motion: reduce) {
  .gburger-lines span {
    transition: none;
  }
}

/* =============================== RESPONSIVE ============================== */
@media (max-width: 1360px) {
  .gnav {
    gap: 10px;
  }

  .gmenu {
    max-width: min(760px, 52vw);
  }

  .nav-actions {
    flex-shrink: 0;
  }
}

@media (max-width: 1180px) {
  /* Меню не помещается в строку — прячем меню и языковой переключатель, всё
     уходит в бургер-drawer. !important — чтобы перебить возможный инлайн base
     display (импорт до фикса parseStylesheet мог заинлайнить .gmenu/.language-switch). */
  .gmenu,
  .nav-actions > .language-switch {
    display: none !important;
  }

  .gburger {
    display: inline-flex !important;
  }
}

@media (max-width: 980px) {
  .gmenu {
    justify-content: flex-start;
    max-width: 100%;
  }
}

@media (max-width: 680px) {
  .glogo {
    min-width: 118px;
  }

  .glogo img {
    width: 118px;
    height: 38px;
  }

  /* Телефон целиком в drawer — без огрызка-иконки .arw в строке. */
  .nav-actions > .gbook {
    display: none !important;
  }

  .language-switch {
    min-width: 78px;
    min-height: 44px;
  }

  .language-switch button {
    width: 31px;
    height: 31px;
  }

  .gmenu a {
    padding: 8px 12px;
    font-size: 12px;
  }
}

@media (max-width: 560px) {
  .gnav {
    top: 8px;
    width: calc(100% - 16px);
    padding: 10px;
    gap: 8px;
    border-radius: 20px;
  }

  .gmenu {
    padding: 4px;
  }

  .gmenu a {
    min-height: 34px;
    padding: 7px 10px;
  }
}

@media (max-width: 380px) {
  .glogo {
    min-width: 106px;
  }

  .glogo img {
    width: 106px;
  }

  .language-switch {
    min-width: 72px;
  }

  .gmenu a {
    padding: 7px 9px;
  }
}

/* ===================== ПОЛНОЭКРАННОЕ БУРГЕР-МЕНЮ (drawer) ===================== */
.gnav-drawer {
  position: fixed;
  inset: 0;
  z-index: 9990;
  display: flex;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  background: rgba(13, 15, 18, .92);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  transition: opacity .35s ease, visibility .35s ease;
}

.gnav-drawer.is-open {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
}

.gnav-drawer-panel {
  position: relative;
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
  padding: clamp(92px, 13vh, 140px) clamp(20px, 6vw, 60px) clamp(28px, 6vh, 64px);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

.gnav-drawer-close {
  align-self: flex-end;
  min-height: 46px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px 10px 22px;
  border: 1px solid rgba(255, 255, 255, .28);
  border-radius: 999px;
  background: rgba(255, 255, 255, .12);
  color: #fff;
  cursor: pointer;
  font-size: 14px;
  font-weight: 800;
  transition: background .25s ease;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.gnav-drawer-close:hover {
  background: rgba(255, 255, 255, .22);
}

.gnav-drawer-close span {
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #fff;
  color: var(--ink);
  font-size: 18px;
  font-weight: 900;
  line-height: 1;
}

.gnav-drawer-phone {
  align-self: flex-start;
  margin-top: clamp(16px, 3vh, 28px);
  color: #fff;
  font-size: clamp(22px, 5vw, 32px);
  font-weight: 800;
}

.gnav-drawer-lang {
  align-self: flex-start;
  margin-top: clamp(16px, 3vh, 28px);
}

.gnav-drawer-menu {
  display: flex;
  flex-direction: column;
  margin-top: clamp(20px, 3vh, 32px);
}

.gnav-drawer-menu a {
  padding: clamp(12px, 2.2vh, 20px) 4px;
  border-bottom: 1px solid rgba(255, 255, 255, .1);
  color: rgba(255, 255, 255, .92);
  font-size: clamp(28px, 6vw, 54px);
  font-weight: 700;
  line-height: 1.1;
  transition: color .2s ease, padding-left .2s ease;
}

.gnav-drawer-menu a:hover,
.gnav-drawer-menu a.active {
  color: var(--gold);
  padding-left: 14px;
}

body.gnav-menu-open {
  overflow: hidden;
}

/* Появление пунктов меню каскадом */
@keyframes gnavDrawerLinkIn {
  from {
    opacity: 0;
    transform: translateY(16px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.gnav-drawer.is-open .gnav-drawer-menu a {
  animation: gnavDrawerLinkIn .45s ease both;
}

.gnav-drawer.is-open .gnav-drawer-menu a:nth-child(2) { animation-delay: .05s; }
.gnav-drawer.is-open .gnav-drawer-menu a:nth-child(3) { animation-delay: .1s; }
.gnav-drawer.is-open .gnav-drawer-menu a:nth-child(4) { animation-delay: .15s; }
.gnav-drawer.is-open .gnav-drawer-menu a:nth-child(5) { animation-delay: .2s; }
.gnav-drawer.is-open .gnav-drawer-menu a:nth-child(6) { animation-delay: .25s; }
.gnav-drawer.is-open .gnav-drawer-menu a:nth-child(7) { animation-delay: .3s; }
.gnav-drawer.is-open .gnav-drawer-menu a:nth-child(n+8) { animation-delay: .35s; }

@media (prefers-reduced-motion: reduce) {
  .gnav-drawer {
    transition: none;
  }

  .gnav-drawer.is-open .gnav-drawer-menu a {
    animation: none;
  }
}

/* ==== nav-logo-theme v2 ====
   Логотип под цвет текста шапки: .glogo-light — при белом тексте (logo-light
   и до первого срабатывания скрипта), .glogo-dark — при тёмном (logo-dark).
   Тёмная картинка наложена на светлую: размер и сдвиг у обеих общие
   (.glogo img), смена — прозрачностью за то же время, что и у текста шапки
   (transition у .glogo img в CSS блока). Картинки меняются в CMS;
   перекрашивать их фильтром не нужно, поэтому у светлой темы только тень. */
.glogo {
  position: relative;
}

.glogo .glogo-dark {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  margin: auto 0;
  opacity: 0;
  pointer-events: none;
}

.gnav.logo-dark .glogo .glogo-light {
  opacity: 0;
}

.gnav.logo-dark .glogo .glogo-dark {
  opacity: 1;
}

.gnav.logo-light .glogo img {
  filter: drop-shadow(0 2px 16px rgba(0, 0, 0, .28));
}
